// Minimal Beacon Dash game targeting <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = (canvas.width = canvas.offsetWidth || 800);
  const height = (canvas.height = canvas.offsetHeight || 600);

  // ----- Game objects -----
  const ship = { x: width / 2, y: height - 50, w: 20, h: 30, speed: 4 };
  const beacons = [];
  const asteroids = [];
  let score = 0;
  let gameOver = false;

  // ----- Input handling -----
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // ----- Utility -----
  const rand = (min, max) => Math.random() * (max - min) + min;
  const rectCollide = (a, b) =>
    a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

  // ----- Spawn -----
  const spawnBeacon = () => {
    beacons.push({ x: rand(0, width - 20), y: -20, w: 20, h: 20, speed: 2 });
  };
  const spawnAsteroid = () => {
    const size = rand(15, 35);
    asteroids.push({ x: rand(0, width - size), y: -size, w: size, h: size, speed: rand(1.5, 3) });
  };
  // spawn intervals
  let beaconTimer = 0,
    asteroidTimer = 0;

  // ----- Main loop -----
  const loop = () => {
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2 - 20);
      ctx.fillText(`Score: ${score}`, width / 2, height / 2 + 20);
      return;
    }

    // clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);

    // starfield (simple)
    ctx.fillStyle = '#444';
    for (let i = 0; i < 50; i++) {
      ctx.fillRect(rand(0, width), rand(0, height), 1, 1);
    }

    // update ship
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    if (keys.ArrowUp) ship.y -= ship.speed;
    if (keys.ArrowDown) ship.y += ship.speed;
    // keep inside canvas
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));
    ship.y = Math.max(0, Math.min(height - ship.h, ship.y));

    // draw ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();

    // spawn beacons/asteroids
    beaconTimer++;
    asteroidTimer++;
    if (beaconTimer > 100) { spawnBeacon(); beaconTimer = 0; }
    if (asteroidTimer > 150) { spawnAsteroid(); asteroidTimer = 0; }

    // update and draw beacons
    ctx.fillStyle = '#ff0';
    for (let i = beacons.length - 1; i >= 0; i--) {
      const b = beacons[i];
      b.y += b.speed;
      ctx.fillRect(b.x, b.y, b.w, b.h);
      // collect
      if (rectCollide(ship, b)) { score++; beacons.splice(i, 1); }
      else if (b.y > height) beacons.splice(i, 1);
    }

    // update and draw asteroids
    ctx.fillStyle = '#888';
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      ctx.beginPath();
      ctx.arc(a.x + a.w / 2, a.y + a.h / 2, a.w / 2, 0, Math.PI * 2);
      ctx.fill();
      if (rectCollide(ship, a)) { gameOver = true; }
      else if (a.y > height) asteroids.splice(i, 1);
    }

    // draw score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);

    requestAnimationFrame(loop);
  };

  // start
  requestAnimationFrame(loop);
})();
